// An editorial menu: actual menu names, photographs always visible, detail on selection.
const plateNumbers={'Tataki de atún':13,'Cazuela de langostinos al pil-pil':14,'Berenjenas fritas con miel de caña':16,'Surtido de croquetas':15,'Tabla de jamón ibérico de bellota':21,'Surtido de quesos con denominación de origen':22,'Arroz con bogavante':17,'Arroz caldoso a la marinera':29,'Lubina':30,'Carrillada de cerdo ibérica al Pedro Ximénez':18,'Solomillo de ternera retinta a la parrilla':19,'Lomo del salmón al cava':31,'Tatín de manzana':39,'Coulant de chocolate':40,'Tarta de queso':41,'Brownie con helado de vainilla':75,'Fruta de temporada':27,'Helado tres sabores':28,'Mojito':43,'Margarita':44,'Piña colada':45,'Daiquiri':46,'Sangría':48,'Vinos':76};
function illustrateMenu(){document.querySelectorAll('.dish-select').forEach(button=>{if(button.querySelector('img'))return;const name=button.textContent;const id=plateNumbers[name];if(!id)return;const img=document.createElement('img');img.src=`assets/venue-${String(id).padStart(2,'0')}.jpg`;img.alt='';img.loading='lazy';img.width=1672;img.height=941;const title=document.createElement('span');title.textContent=name;const arrow=document.createElement('i');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');button.replaceChildren(img,title,arrow);});}
illustrateMenu();new MutationObserver(illustrateMenu).observe(document.querySelector('#menu-items'),{childList:true});
const plateDialog=document.createElement('dialog');plateDialog.className='plate-dialog';plateDialog.setAttribute('aria-label','Detalle del plato');plateDialog.innerHTML='<button class="dialog-close" aria-label="Cerrar plato">×</button><img alt=""><p></p><small>Recreación con IA · La presentación puede variar.</small>';document.body.append(plateDialog);plateDialog.querySelector('button').onclick=()=>plateDialog.close();plateDialog.addEventListener('close',()=>document.body.style.overflow='');
window.addEventListener('dish-select',e=>{if(!matchMedia('(max-width:767px)').matches)return;const id=plateNumbers[e.detail.name];if(!id)return;plateDialog.querySelector('img').src=`assets/venue-${String(id).padStart(2,'0')}.jpg`;plateDialog.querySelector('img').alt=e.detail.name;plateDialog.querySelector('p').textContent=e.detail.name;plateDialog.showModal();document.body.style.overflow='hidden';});
const tasting=document.createElement('section');tasting.className='tasting';tasting.setAttribute('aria-labelledby','tasting-title');
tasting.innerHTML=`<div class="tasting-heading"><span class="eyebrow">DE LA COCINA A LA MESA</span><h2 id="tasting-title">Tres formas<br>de empezar.</h2><div class="rail-controls"><button aria-label="Plato anterior" data-rail="-1">←</button><button aria-label="Plato siguiente" data-rail="1">→</button></div></div><div class="tasting-rail"><a href="#carta" class="taste"><img src="assets/venue-13.jpg" alt="Tataki de atún, recreación con IA" loading="lazy"><span class="taste-no">01</span><div><span>FRESCO / DELICADO</span><h3>Tataki de atún</h3><span>Descubrir la carta ↗</span></div></a><a href="#carta" class="taste"><img src="assets/venue-15.jpg" alt="Croquetas, recreación con IA" loading="lazy"><span class="taste-no">02</span><div><span>CRUJIENTE / CREMOSO</span><h3>Unas croquetas.<br>Y empezamos.</h3><span>Descubrir la carta ↗</span></div></a><a href="#carta" class="taste"><img src="assets/venue-17.jpg" alt="Arroz con bogavante, recreación con IA" loading="lazy"><span class="taste-no">03</span><div><span>PARA COMPARTIR</span><h3>Arroz con bogavante</h3><span>Bajo reserva · mínimo 2 personas ↗</span></div></a></div>`;
document.querySelector('#esencia').before(tasting);
const rail=tasting.querySelector('.tasting-rail');tasting.querySelectorAll('[data-rail]').forEach(b=>b.onclick=()=>rail.scrollBy({left:rail.clientWidth*.72*Number(b.dataset.rail),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}));
const bodega=document.createElement('section');bodega.className='bodega section';bodega.setAttribute('aria-labelledby','bodega-title');
bodega.innerHTML=`<div class="bodega-heading"><span class="eyebrow">04 / LA BODEGA</span><h2 id="bodega-title">La conversación<br>también se sirve.</h2><p>Cinco referencias de nuestra carta de vinos.<br>Consulta añadas y disponibilidad con el equipo.</p><a class="text-link" href="https://www.barlaplazafuengirola.es/carta-de-vinos/" target="_blank" rel="noopener">La carta de vinos ↗</a></div><div class="wine-rail">${['Pago de Carraovejas','Valbuena 5º','Marqués de Riscal Reserva','Matarromera','Habla del Silencio'].map((n,i)=>`<figure><img src="assets/venue-${76+i}.jpg" alt="${n}, recreación con IA" loading="lazy"><figcaption><span>0${i+1}</span>${n}</figcaption></figure>`).join('')}</div>`;
document.querySelector('#galeria').before(bodega);
const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);
let scrollFrame=false;window.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=true;requestAnimationFrame(()=>{const range=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${range?scrollY/range:0})`;scrollFrame=false;});},{passive:true});
const chapterObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.desktop-nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+e.target.id?'location':'false'));}}),{rootMargin:'-20% 0px -60% 0px'});document.querySelectorAll('main>section[id]').forEach(s=>chapterObserver.observe(s));
